-- Peter Jackson (Born: 1961-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Peter Jackson', 'Peter Jackson', 'peter-jackson', 'Male', 'Directing', '1961-10-31', 'Pukerua Bay, Porirua, New Zealand', 'Sir Peter Robert Jackson (born 31 October 1961) is a legendary New Zealand film director, screenwriter, and producer. He is internationally acclaimed for directing, writing, and producing the epic The Lord of the Rings trilogy (2001–2003) and The Hobbit trilogy (2012–2014). The Lord of the Rings: The Return of the King won 11 Academy Awards, tying the record for the most Oscars ever won by a film, earning Jackson Best Director, Best Adapted Screenplay, and Best Picture. His other landmark works include King Kong (2005), Heavenly Creatures (1994), and the acclaimed documentary series The Beatles: Get Back (2021).', 'people/photos/peter-jackson.jpg', 'https://www.facebook.com/PeterJacksonNZ', '{\"facebook\":\"https:\\/\\/www.facebook.com\\/PeterJacksonNZ\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0001392\\/\"}', 1, 'active', 1, @now, @now)
