-- Letitia Wright (Born: 1993-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Letitia Wright', 'Letitia Wright', 'letitia-wright', 'Female', 'Acting', '1993-10-31', 'Georgetown, Guyana', 'Letitia Michelle Wright (born 31 October 1993) is an acclaimed Guyanese-British actress. She achieved international stardom portraying the ingenious tech-master Shuri in the Marvel Cinematic Universe blockbuster Black Panther (2018), earning an NAACP Image Award and a SAG Award. She reprised the role in Avengers: Infinity War (2018), Avengers: Endgame (2019), and took on the mantle of the Black Panther in Black Panther: Wakanda Forever (2022). Wright also earned a Primetime Emmy nomination for Black Mirror: Black Museum and starred in Kenneth Branagh\'s Death on the Nile (2022).', 'people/photos/letitia-wright.jpg', 'https://www.instagram.com/letitiawright', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/letitiawright\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm4004793\\/\"}', 1, 'active', 1, @now, @now)
