-- Rob Schneider (Born: 1963-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Rob Schneider', 'Rob Schneider', 'rob-schneider', 'Male', 'Acting', '1963-10-31', 'San Francisco, California, USA', 'Robert Michael Schneider (born October 31, 1963) is an American actor, comedian, screenwriter, and director. A veteran of Saturday Night Live (1988–1994), Schneider transitioned to a wildly successful film comedy career, headlining box office hits such as Deuce Bigalow: Male Gigolo (1999), The Animal (2001), and The Hot Chick (2002). A frequent collaborator of Adam Sandler, he has appeared in comedy classics including The Waterboy, Big Daddy, 50 First Dates, The Longest Yard, and Grown Ups.', 'people/photos/rob-schneider.jpg', 'https://www.instagram.com/robschneider', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/robschneider\",\"twitter\":\"https:\\/\\/twitter.com\\/RobSchneider\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0001705\\/\"}', 1, 'active', 1, @now, @now)
