-- Willow Smith (Born: 2000-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Willow Smith', 'WILLOW', 'willow-smith', 'Female', 'Sound', '2000-10-31', 'Los Angeles, California, USA', 'Willow Camille Reign Smith (born October 31, 2000), known mononymously as WILLOW, is a multi-platinum American singer, songwriter, and actress. The daughter of Will Smith and Jada Pinkett Smith, she made her acting debut alongside her father in the post-apocalyptic thriller I Am Legend (2007) and voiced young Gloria in Madagascar: Escape 2 Africa. She launched her music career at age nine with the global multi-platinum anthem \"Whip My Hair\" and has since evolved into an innovative alternative-rock and pop-punk artist with worldwide smashes like \"Meet Me at Our Spot\" and \"Wait a Minute!\".', 'people/photos/willow-smith.jpg', 'https://www.instagram.com/willowsmith', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/willowsmith\",\"twitter\":\"https:\\/\\/twitter.com\\/OfficialWillow\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm2405238\\/\"}', 1, 'active', 1, @now, @now)
