-- Dermot Mulroney (Born: 1963-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Dermot Mulroney', 'Dermot Mulroney', 'dermot-mulroney', 'Male', 'Acting', '1963-10-31', 'Alexandria, Virginia, USA', 'Dermot Mulroney (born October 31, 1963) is a versatile and prolific American actor. Mulroney is best known for his romantic leading role as Michael O\'Neal in the smash-hit romantic comedy My Best Friend\'s Wedding (1997) opposite Julia Roberts and Cameron Diaz. Over a distinguished four-decade career, his acclaimed films include Young Guns (1988), About Schmidt (2002), Zodiac (2007), August: Osage County (2013), Scream VI (2023), and the runaway romantic comedy hit Anyone But You (2023). On television, he starred in Shameless, Homecoming, and Marvel\'s Secret Invasion.', 'people/photos/dermot-mulroney.jpg', 'https://www.instagram.com/dermotmulroney', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/dermotmulroney\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0000551\\/\"}', 1, 'active', 1, @now, @now)
