-- Piper Perabo (Born: 1976-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Piper Perabo', 'Piper Perabo', 'piper-perabo', 'Female', 'Acting', '1976-10-31', 'Dallas, Texas, USA', 'Piper Lisa Perabo (born October 31, 1976) is an American actress. Perabo had her breakthrough starring as Violet \"Jersey\" Sanford in the iconic cult comedy-drama Coyote Ugly (2000). She starred as CIA operative Annie Walker in the hit spy drama series Covert Affairs (2010–2014), earning a Golden Globe Award nomination. Her other notable film and television credits include Lost and Delirious (2001), Cheaper by the Dozen (2003), The Prestige (2006), Rian Johnson\'s sci-fi thriller Looper (2012), and Taylor Sheridan\'s hit western drama series Yellowstone (2021–present).', 'people/photos/piper-perabo.jpg', 'https://www.instagram.com/piperperabo', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/piperperabo\",\"twitter\":\"https:\\/\\/twitter.com\\/PiperPerabo\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0005305\\/\"}', 1, 'active', 1, @now, @now)
