-- Arjun Bijlani (Born: 1982-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Arjun Bijlani', 'Arjun Bijlani', 'arjun-bijlani', 'Male', 'Acting', '1982-10-31', 'Mumbai, Maharashtra, India', 'Arjun Bijlani (born 31 October 1982) is one of the most prominent and beloved Indian television actors and hosts. He achieved massive popularity starring as Cadet Alekh Sharma in Left Right Left and Mayank Sharma in Miley Jab Hum Tum. He cemented his superstar status in Indian television headlining Ekta Kapoor\'s mega-hit supernatural thriller Naagin (Season 1) as Ritik Singh and the romantic thriller Ishq Mein Marjawan. In 2021, he emerged as the winner of the stunt reality show Fear Factor: Khatron Ke Khiladi 11 and has hosted popular shows like Dance Deewane and India\'s Got Talent.', 'people/photos/arjun-bijlani.jpg', 'https://www.instagram.com/arjunbijlani', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/arjunbijlani\",\"twitter\":\"https:\\/\\/twitter.com\\/Thearjunbijlani\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm3863486\\/\"}', 1, 'active', 1, @now, @now)
