-- Dharmesh Yelande (Born: 1983-10-31)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Dharmesh Yelande', 'Dharmesh Sir', 'dharmesh-yelande', 'Male', 'Acting', '1983-10-31', 'Vadodara, Gujarat, India', 'Dharmesh Yelande (born 31 October 1983), affectionately known as Dharmesh Sir, is a celebrated Indian dancer, choreographer, and actor. He gained national fame as a standout contestant and runner-up on Dance India Dance (Season 2). Yelande made his Bollywood acting debut starring as D in Remo D\'Souza\'s 3D dance blockbuster ABCD: Any Body Can Dance (2013), and reprised his role in Disney\'s ABCD 2 (2015), Banjo (2016), and Street Dancer 3D (2020). He is also a celebrated judge and mentor on popular reality shows including Dance Plus and Dance Deewane.', 'people/photos/dharmesh-yelande.jpg', 'https://www.instagram.com/dharmesh0011', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/dharmesh0011\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm5493019\\/\"}', 1, 'active', 1, @now, @now)
