-- Aishwarya Rai Bachchan (Born: 1973-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Aishwarya Rai Bachchan', 'Aishwarya Rai', 'aishwarya-rai-bachchan', 'Female', 'Acting', '1973-11-01', 'Mangalore, Karnataka, India', 'Aishwarya Rai Bachchan (born 1 November 1973) is a globally renowned Indian actress, cultural ambassador, and the winner of the Miss World 1994 pageant. Celebrated as one of the most influential and beautiful personalities in world cinema, she has won two Filmfare Awards and was honoured with the Padma Shri by the Government of India and the Ordre des Arts et des Lettres by France. Her timeless cinematic masterworks include Mani Ratnam\'s Iruvar and Guru, Sanjay Leela Bhansali\'s Hum Dil De Chuke Sanam and Devdas, Dhoom 2, Jodhaa Akbar, Guzaarish, The Pink Panther 2, and her dual tour-de-force performance as Nandini in Ponniyin Selvan: I and II (2022–2023).', 'people/photos/aishwarya-rai-bachchan.jpg', 'https://www.instagram.com/aishwaryaraibachchan_arb', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/aishwaryaraibachchan_arb\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0706787\\/\"}', 1, 'active', 1, @now, @now)
