-- Penn Badgley (Born: 1986-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Penn Badgley', 'Penn Badgley', 'penn-badgley', 'Male', 'Acting', '1986-11-01', 'Baltimore, Maryland, USA', 'Penn Dayton Badgley (born November 1, 1986) is an American actor and musician. He achieved worldwide stardom starring as Dan Humphrey in The CW\'s hit teen drama series Gossip Girl (2007–2012). He reached new heights of international critical and commercial acclaim starring as the complex, obsessive bookstore manager Joe Goldberg in the Netflix psychological thriller phenomenon YOU (2018–present). In film, Badgley starred in John Tucker Must Die (2006), The Stepfather (2009), Easy A (2010), and the financial thriller Margin Call (2011). He is also the frontman for the indie band MOTHXR and co-hosts the popular podcast Podcrushed.', 'people/photos/penn-badgley.jpg', 'https://www.instagram.com/pennbadgley', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/pennbadgley\",\"twitter\":\"https:\\/\\/twitter.com\\/PennBadgley\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0046033\\/\"}', 1, 'active', 1, @now, @now)
