-- Toni Collette (Born: 1972-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Toni Collette', 'Toni Collette', 'toni-collette', 'Female', 'Acting', '1972-11-01', 'Blacktown, Sydney, Australia', 'Toni Collette (born 1 November 1972) is an internationally revered Australian actress and producer. Over a legendary career spanning independent triumphs and global blockbusters, Collette has won a Primetime Emmy Award, a Golden Globe Award, and earned an Academy Award nomination for Best Supporting Actress for M. Night Shyamalan\'s iconic thriller The Sixth Sense (1999). Her extraordinary body of work includes Muriel\'s Wedding (1994), Little Miss Sunshine (2006), United States of Tara (2009–2011), Rian Johnson\'s Knives Out (2019), Netflix\'s Unbelievable (2019), and her universally lauded, iconic horror performance in Ari Aster\'s Hereditary (2018).', 'people/photos/toni-collette.jpg', 'https://www.instagram.com/tonicolletteofficial', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/tonicolletteofficial\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0001057\\/\"}', 1, 'active', 1, @now, @now)
