-- Anthony Ramos (Born: 1991-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Anthony Ramos', 'Anthony Ramos', 'anthony-ramos', 'Male', 'Acting', '1991-11-01', 'Brooklyn, New York, USA', 'Anthony Ramos Martinez (born November 1, 1991) is an American actor and singer. Ramos rocketed to worldwide fame originating the dual roles of John Laurens and Philip Hamilton in the 2015 Broadway smash Hamilton, winning a Grammy Award and receiving a Primetime Emmy nomination. He earned a Golden Globe nomination starring as Usnavi de la Vega in the feature film adaptation of In the Heights (2021). In Hollywood, Ramos headlined the global blockbuster Transformers: Rise of the Beasts (2023), starred in Twisters (2024), voiced characters in The Bad Guys, and joins the Marvel Cinematic Universe in the series Ironheart.', 'people/photos/anthony-ramos.jpg', 'https://www.instagram.com/anthonyramosofficial', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/anthonyramosofficial\",\"twitter\":\"https:\\/\\/twitter.com\\/ARamosofficial\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm6866160\\/\"}', 1, 'active', 1, @now, @now)
