-- Ileana D'Cruz (Born: 1987-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Ileana D\'Cruz', 'Ileana D\'Cruz', 'ileana-dcruz', 'Female', 'Acting', '1987-11-01', 'Mumbai, Maharashtra, India', 'Ileana D\'Cruz (born 1 November 1987) is a leading Indian actress known for her successful careers in Hindi and Telugu cinema. She established herself as one of Telugu cinema\'s biggest leading ladies with mega-blockbusters like Pokiri (2006), Jalsa (2008), and Kick (2009). D\'Cruz made an extraordinary Bollywood debut in Anurag Basu\'s critically acclaimed masterpiece Barfi! (2012), winning the Filmfare Award for Best Female Debut. Her other hit Hindi films include Main Tera Hero (2014), the gripping crime thriller Rustom (2016), the action thriller Raid (2018), and Do Aur Do Pyaar (2024).', 'people/photos/ileana-dcruz.jpg', 'https://www.instagram.com/ileana_official', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/ileana_official\",\"twitter\":\"https:\\/\\/twitter.com\\/Ileana_Official\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm2258852\\/\"}', 1, 'active', 1, @now, @now)
