-- Ishaan Khatter (Born: 1995-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Ishaan Khatter', 'Ishaan Khatter', 'ishaan-khatter', 'Male', 'Acting', '1995-11-01', 'Mumbai, Maharashtra, India', 'Ishaan Khatter (born 1 November 1995) is a highly talented Indian actor. Son of actors Rajesh Khattar and Neelima Azeem and brother of Shahid Kapoor, Khatter made a sensational international acting debut in Majid Majidi\'s acclaimed drama Beyond the Clouds (2017), winning the Filmfare Award for Best Male Debut. He achieved mainstream stardom headlining the romantic drama Dhadak (2018) alongside Janhvi Kapoor. Khatter won widespread praise for Mira Nair\'s BBC miniseries A Suitable Boy (2020), the war drama Pippa (2023), and starred in Netflix\'s international mystery series The Perfect Couple (2024) opposite Nicole Kidman and Liev Schreiber.', 'people/photos/ishaan-khatter.jpg', 'https://www.instagram.com/ishaankhatter', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/ishaankhatter\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm2440938\\/\"}', 1, 'active', 1, @now, @now)
