-- Anthony Kiedis (Born: 1962-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Anthony Kiedis', 'Anthony Kiedis', 'anthony-kiedis', 'Male', 'Sound', '1962-11-01', 'Grand Rapids, Michigan, USA', 'Anthony Kiedis (born November 1, 1962) is an American singer, songwriter, and musician best known as the charismatic frontman and founding member of the legendary rock band Red Hot Chili Peppers since 1983. Inducted into the Rock and Roll Hall of Fame in 2012, Kiedis has led the band through multi-platinum historic albums including Blood Sugar Sex Magik (1991), Californication (1999), By the Way (2002), and Stadium Arcadium (2006). He is also the author of the bestselling 2004 autobiography Scar Tissue.', 'people/photos/anthony-kiedis.jpg', 'https://redhotchilipeppers.com', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/chilipeppers\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0452373\\/\"}', 1, 'active', 1, @now, @now)
