-- Padmini Kolhapure (Born: 1965-11-01)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Padmini Kolhapure', 'Padmini Kolhapure', 'padmini-kolhapure', 'Female', 'Acting', '1965-11-01', 'Mumbai, Maharashtra, India', 'Padmini Kolhapure (born 1 November 1965) is an iconic veteran Indian actress and singer who worked extensively in Hindi cinema. Beginning as a celebrated child artist in films like Raj Kapoor\'s Satyam Shivam Sundaram (1978) and Sajan Bina Suhagan, she achieved immense stardom at just fifteen, winning the Filmfare Award for Best Supporting Actress for B. R. Chopra\'s Insaf Ka Tarazu (1980). She subsequently won the Filmfare Award for Best Actress for her landmark performance in Raj Kapoor\'s Prem Rog (1982). Her other beloved classics include Ahista Ahista (1981), Woh Saat Din (1983), Pyar Jhukta Nahin (1985), and Ashutosh Gowariker\'s Panipat (2019).', 'people/photos/padmini-kolhapure.jpg', 'https://www.instagram.com/padminikolhapure', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/padminikolhapure\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0464069\\/\"}', 1, 'active', 1, @now, @now)
